class Solution:
    def allHeardTime(self, times: List[List[int]], n: int, k: int) -> int:
        g = defaultdict(list)
        for u, v, w in times: g[u].append((v, w))
        dist = {}; h = [(0, k)]
        while h:
            d, v = heappop(h)
            if v in dist: continue
            dist[v] = d
            for u, w in g[v]:
                if u not in dist: heappush(h, (d + w, u))
        return max(dist.values()) if len(dist) == n else -1

