function allHeardTime(times, n, k) {
  const d = new Array(n + 1).fill(Infinity); d[k] = 0;
  for (let i = 0; i < n; i++) for (const [u, v, w] of times) if (d[u] + w < d[v]) d[v] = d[u] + w;
  let m = 0; for (let i = 1; i <= n; i++) m = Math.max(m, d[i]);
  return m === Infinity ? -1 : m;
}
